import java.util.concurrent.CompletableFuture;

public class Main {
    public static void main(String[] args) {
        // Pipeline 1: supply -> append -> uppercase -> print -> notify
        CompletableFuture.supplyAsync(() -> "Arcane")
            // TODO: thenApply to append " Surge"
            // TODO: thenApply to convert to uppercase
            // TODO: thenAccept to print "Final spell: " + result
            // TODO: thenRun to print "Pipeline complete"
            .join();

        // Pipeline 2: error handling with exceptionally
        String result = CompletableFuture.<String>supplyAsync(() -> {
            throw new RuntimeException("out of mana");
        }).exceptionally(e -> "Spell fizzled").join();
        System.out.println(result);
    }
}

