import java.util.concurrent.CompletableFuture;
public class Main {
    public static void main(String[] args) {
        CompletableFuture.supplyAsync(() -> 10)
            .thenApply(n -> n * 3)
            .thenApply(n -> n + 5)
            .thenAccept(n -> System.out.println("Value: " + n))
            .join();
    }
}

